#define Bailoutradius 2.0
bool isVec2NaN(vec2 v) { 
    return isnan(v.x) || isnan(v.y); 
}

vec2 fractalFunction(vec2 z, vec2 c) {
    float real = z.x*z.x - z.y*z.y;
    float imaginary = 2.0*z.x*z.y;

    return vec2(real, imaginary) + c;
}
int numberOfIterationsFromPoint(vec2 z, int maxiterations) {
    vec2 c = z;
    vec2 zOld = z;
    int A = 128;
    int B = 0;

    for(int i = 0; i < maxiterations; i+=A) {

        for(int n = 0; n < A; n++) z = fractalFunction(z,c);


        if(z.x*z.x+z.y*z.y > Bailoutradius*Bailoutradius || isVec2NaN(z)) {
            z = zOld;
            for(int n = i; n < min(i+A, maxiterations); n++) {
                if(z.x*z.x+z.y*z.y > Bailoutradius*Bailoutradius) {
                    return n;
                }
                z = fractalFunction(z,c);

            }
        }

        zOld = z;
    }
    return B;
}

void mainImage( out vec4 fragColor, in vec2 fragCoord )
{
    // Normalized pixel coordinates (from 0 to 1)
    vec2 uv = fragCoord/iResolution.xy;
    vec2 z = uv*3.0-1.5;
    z.x *= iResolution.x/iResolution.y;
    int number = numberOfIterationsFromPoint(z, 50000);
    // Time varying pixel color
    vec3 col = (vec3(float(number))*0.02);
    //if(col.x == 1.0) col = vec3(0.0);

    // Output to screen
    fragColor = vec4(col,1.0);
}
